def verify_isbn(isbn: str) -> str:
    def calculate_checksum(isbn: str) -> int:
        total = 0
        for i, char in enumerate(isbn, start=1):
            if char == 'X':
                total += 10 * (10 - i)
            else:
                total += int(char) * (10 - i)
        return total % 11

    parts = isbn.split('-')
    if len(parts) != 4 or not parts[0].isdigit() or not parts[1].isdigit() or not parts[2].isdigit() or not parts[3].isdigit():
        raise ValueError("Invalid ISBN format")

    isbn_numbers = parts[2] + parts[3]
    actual_checksum = calculate_checksum(isbn_numbers)
    calculated_checksum = calculate_checksum(isbn_numbers + 'X' if actual_checksum == 0 else str(11 - actual_checksum))

    if calculated_checksum == 10:
        corrected_isbn = isbn_numbers[:-1] + 'X'
    else:
        corrected_isbn = isbn_numbers + str(calculated_checksum)

    return "Right" if isbn[3:] == corrected_isbn else isbn[:2] + '-' + isbn[2] + '-' + corrected_isbn + '-' + isbn[-1]

def count_passing_ways(n: int, m: int) -> int:
    MOD = 10**9 + 7
    dp = [[0] * (n + 1) for _ in range(m + 1)]
    dp[0][0] = 1

    for i in range(1, m + 1):
        dp[i][0] = 1
        for j in range(1, n + 1):
            dp[i][j] = (dp[i - 1][(j - 1) % n] + dp[i - 1][j % n]) % MOD

    return dp[m][0]

def max_happiness(n: int, m: int, items: List[Tuple[int, int]]) -> int:
