    for price, value in items:
        for j in range(n, price - 1, -1):
            dp[j] = max(dp[j], dp[j - price] + value)
    return dp[n]

def polynomial_to_string(n: int, coeffs: List[int]) -> str:
    terms = []
    for i in range(n, -1, -1):
        coeff = coeffs[n - i]
        if coeff == 0:
            continue
        if i == 0:
            term = f"{abs(coeff)}"
        elif i == 1:
            if coeff == 1:
                term = "x"
            elif coeff == -1:
                term = "-x"
            else:
                term = f"{coeff}x"
        else:
            if coeff == 1:
                term = f"x^{i}"
            elif coeff == -1:
                term = f"-x^{i}"
            else:
                term = f"{coeff}x^{i}"
        terms.append(term)
    return '-'.join(terms)

def decode(encoded: str, original: str, message: str) -> str:
    if len(encoded) != len(original):
        return "Failed"

    mapping = {}
    for e, o in zip(encoded, original):
        if e in mapping and mapping[e] != o:
            return "Failed"
        mapping[e] = o

    if len(mapping) != len(set(mapping.values())):
        return "Failed"

    decoded = ''.join(mapping.get(c, 'X') for c in message)

    for c in set(decoded):
        if decoded.count(c) != message.count(c):
            return "Failed"

    return decoded

def largest_prime_factor(n: int) -> int:
    def is_prime(num: int) -> bool:
        if num <= 1:
            return False
        for i in range(2, int(num**0.5) + 1):
            if num % i == 0:
                return False
        return True

    for i in range(2, int(n**0.5) + 1):
        if n % i == 0 and is_prime(i):
            return n // i
    return n

def count_partitions(n: int, k: int, x: int) -> int:
    def helper(n, k, x):
        if n == 0 and k == 0:
            return 1
        if n < 0 or k < 0 or x > n:
            return 0
        return helper(n - x, k - 1, x) + helper(n, k, x + 1)
    return helper(n, k, x)

def count_sequences(n: int, last: int, memo: dict) -> int:
    if last in memo:
        return memo[last]

    count = 0
    for i in range(1, last // 2 + 1):
        count += count_sequences(n, i, memo)

    memo[last] = count + 1
    return memo[last]

def count_coprime_pairs(x0: int, y0: int) -> int:
    from math import gcd
    count = 0
    quotient = y0 // x0
    for a in range(1, quotient + 1):
        if quotient % a == 0:
            b = quotient // a
            if gcd(a, b) == 1:
                count += 1 if a == b else 2
    return count

def preorder_traversal(inorder: str, postorder: str) -> str:
    if not inorder or not postorder:
        return ""

    root = postorder[-1]
    index = inorder.index(root)

    left_inorder = inorder[:index]
    right_inorder = inorder[index + 1:]

    left_postorder = postorder[:index]
    right_postorder = postorder[index:-1]

    return root + preorder_traversal(left_inorder, left_postorder) + preorder_traversal(right_inorder, right_postorder)

