def generate_numbers(n, rules) -> int:
    queue = deque([n])
    visited = set([n])

    while queue:
        current = queue.popleft()
        current_str = str(current)

        for i in range(len(current_str)):
            digit = int(current_str[i])
            for x, y in rules:
                if digit == x:
                    transformed = int(current_str[:i] + str(y) + current_str[i+1:])
                    if transformed not in visited:
                        visited.add(transformed)
                        queue.append(transformed)

    return len(visited)

