def minimum_students_to_leave(heights):
    n = len(heights)
    if n <= 2:
        return n - 1

    max_heights = [0] * n
    max_heights[0] = 1
    for i in range(1, n):
        max_heights[i] = max_heights[i - 1] + 1 if heights[i] > heights[i - 1] else 1

    min_heights = [0] * n
    min_heights[n - 1] = 1
    for i in range(n - 2, -1, -1):
        min_heights[i] = min_heights[i + 1] + 1 if heights[i] > heights[i + 1] else 1

    max_total = 0
    for i in range(n):
        max_total = max(max_total, max_heights[i] + min_heights[i] - 1)

    return n - max_total

def min_groups(w, n, prices):
    prices.sort()
    groups = 0
    i = 0
    while i < n:
        if i + 1 < n and prices[i] + prices[i + 1] <= w:
            i += 2
        else:
            i += 1
        groups += 1
    return groups
